555	// ---- 보간: 100ms 전 시점을 그린다. 그 시점의 서버 틱을 사격 판정에 함께 보낸다 ----
556	const lerp = (a, b, t) => a + (b - a) * t;
557	function lerpAngle(a, b, t) {
558	  let d = b - a;
559	  while (d > Math.PI) d -= Math.PI * 2;
560	  while (d < -Math.PI) d += Math.PI * 2;
561	  return a + d * t;
562	}
