564	function viewAt(now) {
565	  if (!snaps.length) return null;
566	  const t = now - INTERP_MS;
567	  let s0 = snaps[0], s1 = snaps[0];
568	  if (t >= snaps[snaps.length - 1].t) s0 = s1 = snaps[snaps.length - 1];
569	  else for (let i = 0; i < snaps.length - 1; i++)
570	    if (snaps[i + 1].t >= t) { s0 = snaps[i]; s1 = snaps[i + 1]; break; }
571	  const f = s1.t > s0.t ? Math.max(0, Math.min(1, (t - s0.t) / (s1.t - s0.t))) : 0;
572	  return { s0, s1, f, tick: lerp(s0.tick, s1.tick, f) };
573	}
574	
575	function posAt(view, id) {
576	  const p0 = view.s0.ps.get(id), p1 = view.s1.ps.get(id) ?? p0;
577	  if (!p0) return null;
578	  // 부활처럼 순간이동한 경우엔 보간하지 않음
579	  const f = Math.hypot(p1.x - p0.x, p1.z - p0.z) > 3 ? 1 : view.f;
580	  return {
581	    x: lerp(p0.x, p1.x, f), y: lerp(p0.y, p1.y, f), z: lerp(p0.z, p1.z, f),
582	    yaw: lerpAngle(p0.yaw, p1.yaw, f), pitch: lerp(p0.pitch, p1.pitch, f), alive: p1.alive, w: p1.w,
583	  };
584	}
