590	    a.root.visible = id !== hideId && !(id === myId && (alive || ghost));
591	    setAvatarGhost(a, p.ghost);
592	    const speed = Math.hypot(p.x - a.root.position.x, p.z - a.root.position.z) / Math.max(dt, 1e-3);
593	    // 망령의 y는 눈높이라 발 위치로 내리고 둥둥 떠 있게
594	    a.root.position.set(p.x, p.ghost ? p.y - P.eye + Math.sin(performance.now() / 400 + id) * 0.1 : p.y, p.z);
595	    a.root.rotation.y = p.yaw;
596	    a.root.scale.setScalar(scaleOf(id));
597	    a.head.rotation.x = p.pitch * 0.6;
598	    a.armR.rotation.x = a.armL.rotation.x = Math.PI / 2 + p.pitch;
599	    setAvatarWeapon(a, p.w);
600	    const amt = p.alive ? Math.min(1, speed / P.speed) : 0;
601	    if (p.ghost) a.fall = 0;
602	    a.phase += dt * 10 * amt;
603	    const swing = Math.sin(a.phase) * 0.7 * amt;
