606	    if (!p.ghost) a.fall += ((p.alive ? 0 : 1) - a.fall) * Math.min(1, dt * 8);
607	    a.body.rotation.x = -a.fall * Math.PI / 2;
608	    a.tag.visible = p.alive;
609	    a.flash = Math.max(0, a.flash - dt);
