615	function localShot(inp, spread) {
616	  const o = [me.x, me.y + P.eye * scaleOf(myId), me.z];
617	  const w = WEAPONS[me.w];
618	  const from = muzzleWorld();
619	  for (const d of shotDirs(me, inp.y, inp.p, spread, inp.s)) {
620	    const wall = rayBlocks(map, o, d, w.range);
621	    let best = wall ? wall.t : w.range, hitPlayer = false;
622	    for (const [id, a] of others) {
623	      if (id === myId || !a.root.visible || a.fall > 0.5 || a.ghost) continue;
624	      for (const hb of hitboxes(a.root.position, scaleOf(id))) {
625	        const t = rayBox(o, d, hb.min, hb.max);
626	        if (t < best) { best = t; hitPlayer = true; }
627	      }
628	    }
629	    const end = new THREE.Vector3(o[0] + d[0] * best, o[1] + d[1] * best, o[2] + d[2] * best);
630	    tracer(scoped() ? new THREE.Vector3(o[0], o[1] - 0.15, o[2]) : from, end);
631	    if (wall && !hitPlayer) {
632	      const b = map.get(...wall.cell);
633	      burst(end, BLOCK_COLORS[b]?.[0] ?? '#888', w.pellets > 1 ? 1 : 4, 0.06);
634	      if (BLOCK_HP[b] && w.pellets === 1) sfx.crack();
635	    }
636	  }
637	  gunFired();
638	  sfx.shot(me.w);
639	}
